#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007

int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    int robots[N], exits[M];
    for (int i = 0; i < N; i++) scanf("%d", &robots[i]);
    for (int i = 0; i < M; i++) scanf("%d", &exits[i]);

    qsort(robots, N, sizeof(int), cmp);
    qsort(exits, M, sizeof(int), cmp);

    int dp[M+1];
    for (int j = 0; j <= M; j++) dp[j] = 1;

    for (int i = 1; i <= N; i++) {
        int new_dp[M+1];
        new_dp[0] = 0;
        for (int j = 1; j <= M; j++) {
            new_dp[j] = new_dp[j-1];
            if (robots[i-1] <= exits[j-1]) {
                new_dp[j] = (new_dp[j] + dp[j-1]) % MOD;
            }
        }
        for (int j = 0; j <= M; j++) dp[j] = new_dp[j];
    }

    printf("%d\n", dp[M]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

long long power(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

long long inv(long long a, long long mod) {
    return power(a, mod - 2, mod);
}

// C(n, k) mod p
long long comb(long long n, long long k) {
    if (k < 0 || k > n) return 0;
    if (k == 0) return 1;
    long long num = 1, den = 1;
    for (long long i = 0; i < k; i++) {
        num = num * ((n - i) % MOD) % MOD;
        den = den * ((i + 1) % MOD) % MOD;
    }
    return num % MOD * inv(den, MOD) % MOD;
}

int main() {
    long long N, M;
    scanf("%lld %lld", &N, &M);
    // Answer is C(M+N-1, N)
    printf("%lld\n", comb(M + N - 1, N));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    long long *R = (long long *)malloc(sizeof(long long) * N);
    long long *E = (long long *)malloc(sizeof(long long) * M);
    if (!R || !E) return 0;

    for (int i = 0; i < N; i++) scanf("%lld", &R[i]);
    for (int i = 0; i < M; i++) scanf("%lld", &E[i]);

    qsort(R, N, sizeof(long long), cmp_ll);
    qsort(E, M, sizeof(long long), cmp_ll);

    /*
      Let dp[j] = number of ways to assign processed robots using only first j exits,
      with order preserved (i-th robot matched to some exit index increasing).
      Transition for robot i:
        newdp[j] = newdp[j-1] + dp[j-1] * [E[j-1] >= R[i-1]]
      Explanation:
        - skip exit j
        - or use exit j for current robot if exit is at or to the right of robot
      Robots can only move right to reach exits.
    */

    long long *dp = (long long *)calloc(M + 1, sizeof(long long));
    long long *ndp = (long long *)calloc(M + 1, sizeof(long long));
    if (!dp || !ndp) return 0;

    for (int j = 0; j <= M; j++) dp[j] = 1;  // 0 robots: one way

    for (int i = 1; i <= N; i++) {
        ndp[0] = 0;
        for (int j = 1; j <= M; j++) {
            long long val = ndp[j - 1]; // skip exit j
            if (E[j - 1] >= R[i - 1]) {
                val += dp[j - 1];       // use exit j for robot i
                if (val >= MOD) val -= MOD;
            }
            ndp[j] = val;
        }
        long long *tmp = dp;
        dp = ndp;
        ndp = tmp;
    }

    printf("%lld\n", dp[M] % MOD);

    free(R);
    free(E);
    free(dp);
    free(ndp);
    return 0;
}

