const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<int> robots(N), exits(M);
    for (int i = 0; i < N; i++) cin >> robots[i];
    for (int i = 0; i < M; i++) cin >> exits[i];

    sort(robots.begin(), robots.end());
    sort(exits.begin(), exits.end());

    vector<long long> dp(N + 1, 0);
    dp[0] = 1;

    int e_idx = 0;
    for (int i = 0; i < N; i++) {
        while (e_idx < M && exits[e_idx] < robots[i]) e_idx++;

        int left_exits = e_idx;
        int right_exits = M - e_idx;

        long long ways = 0;
        if (left_exits > 0) ways = (ways + dp[i]) % MOD;  // assign left
        if (right_exits > 0) ways = (ways + dp[i]) % MOD; // assign right

        dp[i + 1] = ways;
    }

    cout << dp[N] % MOD << '\n';
    return 0;
}

