const int MOD = 1e9 + 7;

int main() {
    int N, M;
    cin >> N >> M;

    vector<long long> r(N), e(M);
    for (int i = 0; i < N; i++) cin >> r[i];
    for (int i = 0; i < M; i++) cin >> e[i];

    sort(r.begin(), r.end());
    sort(e.begin(), e.end());

    // dp[i][j] = ways to assign first i robots using exits among first j
    // dp[i][j] = dp[i][j-1] + (e[j-1] >= r[i-1] ? dp[i-1][j-1] : 0)
    vector<vector<long long>> dp(N+1, vector<long long>(M+1, 0));
    for (int j = 0; j <= M; j++) dp[0][j] = 1;

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= M; j++) {
            dp[i][j] = dp[i][j-1];
            if (e[j-1] >= r[i-1]) {
                dp[i][j] = (dp[i][j] + dp[i-1][j-1]) % MOD;
            }
        }
    }

    cout << dp[N][M] << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<long long> R(N), E(M);
    for (int i = 0; i < N; i++) cin >> R[i];
    for (int i = 0; i < M; i++) cin >> E[i];

    sort(R.begin(), R.end());
    sort(E.begin(), E.end());

    // dp[j] = number of ways after processing some robots,
    // using only first j exits, with the j-th exit still available/not necessarily used.
    // Transition:
    // For each robot in increasing order, it can use any exit to its left among remaining exits.
    // Standard matching DP:
    // newdp[j] = newdp[j-1] + dp[j-1] if E[j-1] < robot
    //            newdp[j-1] otherwise
    //
    // Symmetrically, robots can also move right, so each robot can use any exit.
    // Since disappearance only requires coinciding with an exit and no restriction on direction/time,
    // the problem reduces to counting injective assignments from robots to exits.
    // Thus answer = P(M, N) = M * (M-1) * ... * (M-N+1), if M >= N, else 0.

    if (M < N) {
        cout << 0 << '\n';
        return 0;
    }

    long long ans = 1;
    for (int i = 0; i < N; i++) {
        ans = ans * (M - i) % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

