        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        // C(N+M-1, N)
        long n = N + M - 1;
        long k = N;
        // compute C(n, k)
        long num = 1, den = 1;
        for (long i = 0; i < k; i++) {
            num = num * ((n - i) % MOD) % MOD;
            den = den * (i + 1) % MOD;
        }
        System.out.println(num * modpow(den, MOD - 2, MOD) % MOD);
    }

    static long modpow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        long[] robots = new long[N];
        long[] exits = new long[M];

        for (int i = 0; i < N; i++) robots[i] = fs.nextLong();
        for (int i = 0; i < M; i++) exits[i] = fs.nextLong();

        Arrays.sort(robots);
        Arrays.sort(exits);

        long[] dp = new long[M + 1];
        long[] pref = new long[M + 1];

        // dp[j]: number of ways for processed robots, with the last chosen exit being exits[j-1]
        // pref[j] = sum of dp[1..j]
        // For the first robot, any exit can be chosen.
        for (int j = 1; j <= M; j++) dp[j] = 1;
        buildPrefix(dp, pref, M);

        for (int i = 1; i < N; i++) {
            long[] ndp = new long[M + 1];

            for (int j = 1; j <= M; j++) {
                long limit = 2L * robots[i] - exits[j - 1];
                int k = upperBound(exits, limit); // exits index count <= limit
                // previous chosen exit index t must satisfy:
                // exits[t-1] <= 2*robots[i] - exits[j-1]
                // ways = sum dp[t] for t in [1..k]
                ndp[j] = pref[k];
            }

            dp = ndp;
            buildPrefix(dp, pref, M);
        }

        System.out.println(pref[M] % MOD);
    }

    static void buildPrefix(long[] dp, long[] pref, int M) {
        pref[0] = 0;
        for (int i = 1; i <= M; i++) {
            pref[i] = pref[i - 1] + dp[i];
            if (pref[i] >= MOD) pref[i] -= MOD;
        }
    }

    // returns number of elements <= x in sorted array a
    static int upperBound(long[] a, long x) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] <= x) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
